// Sample-only inference: every value that reaches the model must be a cell, header or ID of the
// built-in synthetic fixtures (fixtures/inventory). sample.json is generated by the web parser
// (web/src/domain/gatewaySample.test.ts), so IDs match the browser's byte for byte.
import sample from "./sample.json";

type Side = "A" | "B";
type Fixture = { datasetId: string; columns: { id: string; header: string }[]; rows: { id: string; cells: string[] }[] };
const FIXTURES = sample as Record<Side, Fixture>;

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const sameStrings = (a: unknown, b: string[]) => Array.isArray(a) && a.length === b.length && a.every((x, i) => x === b[i]);
const fixture = (side: unknown) => (side === "A" || side === "B" ? FIXTURES[side] : undefined);

function cell(side: unknown, rowId: unknown, columnId: unknown): string | undefined {
  const f = fixture(side);
  const col = f?.columns.findIndex((c) => c.id === columnId) ?? -1;
  return col < 0 ? undefined : f!.rows.find((r) => r.id === rowId)?.cells[col];
}

// POST /api/map: only `datasets` is sent to the model.
export function isSampleMap(body: unknown): boolean {
  if (!isObj(body) || !Array.isArray(body.datasets) || body.datasets.length !== 2) return false;
  return body.datasets.every((d) => {
    const f = isObj(d) ? fixture(d.side) : undefined;
    if (!f || !isObj(d) || d.datasetId !== f.datasetId || !Array.isArray(d.columns) || !Array.isArray(d.samples)) return false;
    const columnsMatch =
      d.columns.length === f.columns.length &&
      d.columns.every((c, i) => isObj(c) && c.id === f.columns[i].id && c.header === f.columns[i].header);
    return (
      columnsMatch &&
      d.samples.every((s) => {
        const row = isObj(s) ? f.rows.find((r) => r.id === s.rowId) : undefined;
        return row !== undefined && isObj(s) && sameStrings(s.cells, row.cells);
      })
    );
  });
}

// POST /api/suggest: only `rows` is sent to the model. Every cited field must be the exact fixture
// cell; the API itself checks that each field belongs to the row that owns it.
export function isSampleSuggest(body: unknown): boolean {
  if (!isObj(body) || !Array.isArray(body.rows) || body.rows.length === 0) return false;
  return body.rows.every((r) => {
    if (!isObj(r) || !Array.isArray(r.candidates)) return false;
    return [r.left, ...r.candidates].every(
      (owner) =>
        isObj(owner) &&
        Array.isArray(owner.fields) &&
        owner.fields.length > 0 &&
        owner.fields.every((f) => isObj(f) && f.rowId === owner.rowId && typeof f.value === "string" && cell(f.side, f.rowId, f.columnId) === f.value),
    );
  });
}
